sudo docker exec -e PGPASSWORD='evopass' evo-postgres psql -U evo -d n8n -t -c "SELECT CAST(data AS text) FROM execution_data ed JOIN execution_entity ee ON ed.\"executionId\" = ee.id WHERE ee.\"workflowId\" = 'AAAABBBBCCCCDDDD' AND ee.status = 'error' ORDER BY ee.id DESC LIMIT 1;" > /tmp/n8n_err2.json
cat /tmp/n8n_err2.json | grep -o '\"error\":[^}]*' | head -5